import * as React from 'react'
import { graphql, Link } from 'gatsby'
import { GatsbyImage, IGatsbyImageData, getImage } from 'gatsby-plugin-image'

import "../scss/main.scss"

import Header from "../components/Header"
import Footer from "../components/Footer"
import AccentDots from "../components/AccentDots"

interface GalleryGroup {
  fieldValue: string
  nodes: Array<{
    name: string
    childImageSharp: {
      gatsbyImageData: IGatsbyImageData
    }
  }>
}

interface ImageNode {
  childImageSharp: {
    gatsbyImageData: IGatsbyImageData
  }
}

interface PageProps {
  data: {
    designGalleries: {
      group: GalleryGroup[]
    }
    artImages: {
      nodes: ImageNode[]
    }
    artCount: {
      totalCount: number
    }
  }
}

const CreationsPage: React.FC<PageProps> = ({ data }) => {
  // Get the first art image as the cover for the Art gallery card
  const artCoverImage = data.artImages.nodes[0]?.childImageSharp?.gatsbyImageData
  const artTotal = data.artCount.totalCount

  return (
    <div className="container">
      <Header />
      <div className="gallery-hero">
        <h1>Creations</h1>
        <p>My creative journey in one place — from traditional drawings and paintings to digital design and beyond.</p>
        <AccentDots />
      </div>
      <div className="galleries-container">
        <div className="galleries-grid">
          {/* Art Gallery Card */}
          <Link
            to="/creations/art"
            className="gallery-card"
          >
            {artCoverImage && (
              <GatsbyImage
                image={artCoverImage}
                alt="Art Gallery"
                className="gallery-cover"
              />
            )}
            <div className="gallery-info">
              <h2>Art</h2>
              <p>{artTotal} {artTotal === 1 ? 'piece' : 'pieces'}</p>
            </div>
          </Link>

          {/* Design Gallery Cards */}
          {data.designGalleries.group.map((gallery) => {
            const galleryName = gallery.fieldValue
            const titleOverrides: Record<string, string> = {
              'animation-stills': 'Animation',
            }
            const galleryTitle = titleOverrides[galleryName] || galleryName
              .split('-')
              .map(word => word.charAt(0).toUpperCase() + word.slice(1))
              .join(' ')

            const coverCovers: Record<string, string> = {
              'xmas-designs': 'xmas4',
              'greenwich-designs': 'greenwich6',
              'animation-stills': '26',
            }
            const preferredCover = coverCovers[galleryName]
            const coverNode = preferredCover
              ? gallery.nodes.find(n => n.name === preferredCover)
              : undefined
            const fallbackIndex = Math.floor(gallery.nodes.length / 2)
            const coverImage = (coverNode || gallery.nodes[fallbackIndex])?.childImageSharp?.gatsbyImageData

            return (
              <Link
                key={galleryName}
                to={`/creations/${galleryName}`}
                className="gallery-card"
              >
                {coverImage && (
                  <GatsbyImage
                    image={coverImage}
                    alt={galleryTitle}
                    className="gallery-cover"
                  />
                )}
                <div className="gallery-info">
                  <h2>{galleryTitle}</h2>
                  <p>{gallery.nodes.length} {gallery.nodes.length === 1 ? 'design' : 'designs'}</p>
                </div>
              </Link>
            )
          })}
        </div>
      </div>
      <Footer />
    </div>
  )
}

export const pageQuery = graphql`
  query CreationsQuery {
    designGalleries: allFile(
      filter: {
        sourceInstanceName: { eq: "creations" }
        relativeDirectory: { ne: "" }
      }
      sort: { relativeDirectory: ASC }
    ) {
      group(field: { relativeDirectory: SELECT }) {
        fieldValue
        nodes {
          name
          childImageSharp {
            gatsbyImageData(
              width: 800
              height: 800
              placeholder: BLURRED
              transformOptions: { fit: COVER, cropFocus: CENTER }
            )
          }
        }
      }
    }
    artImages: allFile(
      filter: { sourceInstanceName: { eq: "art" }, name: { eq: "1" } }
      limit: 1
    ) {
      nodes {
        childImageSharp {
          gatsbyImageData(
            width: 300
            height: 300
            placeholder: BLURRED
            transformOptions: { fit: COVER, cropFocus: CENTER }
          )
        }
      }
    }
    artCount: allFile(
      filter: { sourceInstanceName: { eq: "art" } }
    ) {
      totalCount
    }
  }
`

export default CreationsPage
